<section class="article-hero"><div class="container article-hero-inner"><a class="back-link" href="<?= e(url('news')) ?>">← <?= __('news_back') ?></a><div class="article-meta"><span><?= e(field($article,'category')) ?></span><span><?= __('news_by') ?> <?= e(format_date($article['date'])) ?></span></div><h1><?= e(field($article,'title')) ?></h1><p><?= e(field($article,'excerpt')) ?></p></div></section>
<section class="article-content"><div class="container article-layout"><article><img class="article-cover" src="<?= e($article['image']) ?>" alt="<?= e(field($article,'title')) ?>"><?php foreach(field_array($article,'content') as $paragraph): ?><p><?= e($paragraph) ?></p><?php endforeach; ?><div class="article-end"><a class="text-link" href="<?= e(url('news')) ?>">← <?= __('news_back') ?></a></div></article><aside><div class="sticky-card"><span class="eyebrow"><?= __('latest_news') ?></span><?php foreach(array_slice($NEWS,0,3) as $item): if($item['slug']===$article['slug']) continue; ?><a class="side-news" href="<?= e(url('article/'.$item['slug'])) ?>"><small><?= e(format_date($item['date'])) ?></small><strong><?= e(field($item,'title')) ?></strong></a><?php endforeach; ?></div></aside></div></section>
